    pm.expect(jsonbody.code).to.eql(200);
    pm.expect(jsonbody.type).to.eql("unknown");
    //pm.expect(jsonbody.message).to.include("additionalMetadata: Petter");
    const addiMetadata = pm.request.body.formdata.find(a => a.key == "additionalMetadata");
    console.log(addiMetadata);
    if(addiMetadata.key){
        pm.expect(jsonbody.message).to.includes(addiMetadata.key, addiMetadata.value); 
    }
    pm.expect(jsonbody.message).to.include("File uploaded");

    const filebody = pm.request.body.formdata.find(a => a.key == "file");
    if (filebody && filebody.src) {
        const filename = filebody.src.split("/").pop().split("\\").pop();
        pm.expect(jsonbody.message).to.include(filename);
    }
})

